// Machine-learning engine verified against R (glmnet 5.0, pROC, stats::glm, survival) and scikit-learn 1.9.
// Reference values: tests/fixtures/ml-reference.json, regenerated by ml-reference.R then ml-reference.py.
// Random ensembles (forests, survival forests) cannot match another library draw-for-draw, so they get
// property tests: reproducibility for a seed, recovery of known signal, and honest out-of-bag estimates.
import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import * as M from '../web/lib/ml.mjs';
import { syntheticBiomarker } from '../web/lib/ml-demo.mjs';
import { modelCard, tripodDraft } from '../web/lib/ml-report.mjs';

const R = JSON.parse(readFileSync(new URL('./fixtures/ml-reference.json', import.meta.url)));
const S = R.sklearn;
const close = (a, b, tol, label = '') => { [].concat(a).forEach((v, i) => assert.ok(Math.abs(v - [].concat(b)[i]) <= tol, `${label}[${i}] ${v} vs ${[].concat(b)[i]}`)); };
const col = (m, k) => m.map(r => r[k]);

for (const a of [1, 0.5]) {
  test(`elastic-net logistic (alpha ${a}) matches R glmnet coefficients and lambda max`, () => {
    const ref = R[`binomial_a${a}`], fit = M.elasticNet(R.X, R.y, { family: 'binomial', alpha: a, lambda: ref.lambda });
    fit.path.forEach((s, k) => { close(s.beta, col(ref.beta, k), 5e-8, `beta λ${k}`); close(s.b0, ref.a0[k], 5e-9, `a0 λ${k}`); });
    close(M.elasticNet(R.X, R.y, { family: 'binomial', alpha: a, nlambda: 5 }).path[0].lambda, ref.lambdaMax, 1e-12, 'λmax');
  });
  test(`elastic-net Cox (alpha ${a}, Breslow) matches R glmnet coefficients and lambda max`, () => {
    const ref = R[`cox_a${a}`], fit = M.elasticNet(R.X, { time: R.time, status: R.status }, { family: 'cox', alpha: a, lambda: ref.lambda });
    // glmnet stops on relative deviance change; the optimum is flat, so coefficients agree to ~1e-7
    fit.path.forEach((s, k) => close(s.beta, col(ref.beta, k), 2e-7, `beta λ${k}`));
    close(M.elasticNet(R.X, { time: R.time, status: R.status }, { family: 'cox', alpha: a, nlambda: 5 }).path[0].lambda, ref.lambdaMax, 1e-12, 'λmax');
  });
}

test('AUC and DeLong variance and CI match R pROC (tied scores)', () => {
  const r = M.aucDeLong(R.y, R.auc.score);
  close(r.auc, R.auc.auc, 1e-12, 'auc'); close(r.se ** 2, R.auc.var, 1e-14, 'var');
  close([r.lower, r.upper], [R.auc.lower, R.auc.upper], 1e-12, 'ci');
});

test('calibration intercept and slope match R glm', () => {
  const c = M.calibrationLogistic(R.y, R.calib.prob);
  close(c.intercept, R.calib.intercept, 1e-10, 'intercept'); close(c.slope, R.calib.slope, 1e-9, 'slope');
});

test('decision tree and gradient boosting match scikit-learn predictions', () => {
  const tr = R.X.slice(0, 150), y = R.y.slice(0, 150), te = R.X.slice(150);
  const tree = M.fitModel('tree', tr, y, { maxDepth: 3, minLeaf: 1 });
  close(M.predictModel(tree, te).prob, S.tree_proba, 1e-12, 'tree');
  const gbm = M.fitModel('gbm', tr, y, { nTrees: 40, learningRate: 0.1, maxDepth: 3, minLeaf: 10, subsample: 1 });
  close(M.predictModel(gbm, te).prob, S.gbm_proba, 1e-10, 'gbm');
});

test('PCA matches scikit-learn (explained variance; loadings up to sign)', () => {
  const p = M.pca(R.X, { scale: false, components: 4 });
  close(p.explained, S.pca_explained, 1e-10, 'explained'); close(p.variance, S.pca_variance, 1e-10, 'variance');
  p.components.forEach((c, k) => close(c.map(Math.abs), S.pca_components[k].map(Math.abs), 1e-8, `PC${k + 1}`));
});

test('k-means (fixed start) and silhouette match scikit-learn', () => {
  const X3 = R.X.map(r => r.slice(0, 3)), km = M.kmeans(X3, 3, { init: S.kmeans_init });
  assert.deepEqual(km.labels, S.kmeans_labels);
  close(km.inertia, S.kmeans_inertia, 1e-8, 'inertia');
  close(M.silhouette(X3, km.labels), S.silhouette, 1e-12, 'silhouette');
});

test("Harrell's C on out-of-sample risk matches R survival::concordance", () => {
  const m = M.survivalMetrics(R.time, R.status, R.conc.risk);
  close(m.cIndex, R.conc.c, 1e-12, 'C');
});

test('preprocessing is learned on training rows and frozen for new rows', () => {
  const headers = ['a', 'g'], rows = [['1', 'x'], ['', 'y'], ['3', 'x'], ['5', 'z']];
  const pre = M.fitPreprocessor(headers, rows, [{ name: 'a', kind: 'numeric' }, { name: 'g', kind: 'categorical' }]);
  assert.deepEqual(pre.columns, ['a', 'g = y', 'g = z']); // reference = most frequent level (x)
  const t = M.transform(pre, headers, [['', 'w'], ['2', 'z']]);
  assert.deepEqual(t.X, [[3, 0, 0], [2, 0, 1]]); // median 3 from training; unseen level → reference
  assert.equal(t.imputed, 1); assert.equal(t.unseen, 1);
});

test('stratified folds are balanced and reproducible', () => {
  const y = Array.from({ length: 103 }, (_, i) => (i % 4 === 0 ? 1 : 0)), f = M.stratifiedFolds(y, 5, 9);
  assert.deepEqual(f, M.stratifiedFolds(y, 5, 9));
  for (let k = 0; k < 5; k++) { const pos = y.filter((v, i) => v && f[i] === k).length; assert.ok(pos >= 5 && pos <= 6, `fold ${k} has ${pos} positives`); }
});

const demo = syntheticBiomarker();
const H = demo.headers, rows = demo.rows;
const feats = ['age', 'ecog', 'arm', 'tmb', 'KRAS_mut', 'TP53_mut', 'EGFR_mut', 'STK11_mut', 'gene_01', 'gene_02', 'gene_03', 'gene_04', 'gene_05', 'gene_06']
  .map(name => ({ name, kind: ['arm'].includes(name) ? 'categorical' : 'numeric' }));

test('random forest and survival forest are reproducible, recover signal and give honest OOB estimates', () => {
  const pre = M.fitPreprocessor(H, rows, feats), X = M.transform(pre, H, rows).X;
  const oc = M.extractOutcome(H, rows, { type: 'binary', column: 'response', positive: '1' });
  const rf1 = M.randomForest(X, oc.y, { nTrees: 80, seed: 5 }), rf2 = M.randomForest(X, oc.y, { nTrees: 80, seed: 5 });
  assert.deepEqual(rf1.oob, rf2.oob);
  const keep = rf1.oob.map((v, i) => (Number.isFinite(v) ? i : -1)).filter(i => i >= 0);
  const oobAuc = M.aucDeLong(keep.map(i => oc.y[i]), keep.map(i => rf1.oob[i])).auc;
  const trainAuc = M.aucDeLong(oc.y, M.predictModel({ type: 'rf', trees: rf1.trees }, X).prob).auc;
  assert.ok(oobAuc > 0.62 && oobAuc < trainAuc, `OOB AUC ${oobAuc} should show signal and be below training AUC ${trainAuc}`);
  const so = M.extractOutcome(H, rows, { type: 'survival', time: 'os_months', event: 'death' });
  const rsf = M.randomSurvivalForest(X, so.time, so.status, { nTrees: 60, seed: 3 });
  const ok = rsf.oob.map((h, i) => (h ? i : -1)).filter(i => i >= 0);
  const c = M.survivalMetrics(ok.map(i => so.time[i]), ok.map(i => so.status[i]), ok.map(i => rsf.oob[i].reduce((s, v) => s + v, 0))).cIndex;
  assert.ok(c > 0.62, `RSF OOB C ${c}`);
});

test('cross-validated elastic-net Cox selects the true prognostic features and reports calibration', () => {
  const r = M.trainEvaluate({ headers: H, rows, outcome: { type: 'survival', time: 'os_months', event: 'death' }, features: feats, model: 'cox_enet', folds: 5, seed: 11, subgroup: 'sex', site: 'site', importance: false });
  assert.ok(r.summary.mean > 0.62, `CV C ${r.summary.mean}`);
  const chosen = r.coefficients.map(c => c.name);
  for (const f of ['ecog', 'KRAS_mut', 'gene_01']) assert.ok(chosen.includes(f), `${f} should be selected (got ${chosen.join(', ')})`);
  assert.equal(r.calibration.length, 5);
  assert.equal(r.sites.length, 3);
  assert.ok(r.subgroups.every(s => Number.isFinite(s.cIndex)));
  assert.ok(Number.isFinite(r.pooled.ipa) && Number.isFinite(r.pooled.brier));
  // reproducible
  const r2 = M.trainEvaluate({ headers: H, rows, outcome: { type: 'survival', time: 'os_months', event: 'death' }, features: feats, model: 'cox_enet', folds: 5, seed: 11, importance: false });
  assert.equal(r2.summary.mean, r.summary.mean);
});

test('every model trains under cross-validation, and exported models re-apply identically', () => {
  for (const [type, outcome] of [['logit_enet', { type: 'binary', column: 'response', positive: '1' }], ['tree', { type: 'binary', column: 'response', positive: '1' }], ['rf', { type: 'binary', column: 'response', positive: '1' }], ['gbm', { type: 'binary', column: 'response', positive: '1' }],
    ['cox_enet', { type: 'survival', time: 'os_months', event: 'death' }], ['rsf', { type: 'survival', time: 'os_months', event: 'death' }], ['gbm_cox', { type: 'survival', time: 'os_months', event: 'death' }]]) {
    const params = { rf: { nTrees: 40 }, rsf: { nTrees: 30 }, gbm: { nTrees: 40 }, gbm_cox: { nTrees: 40 } }[type] || {};
    const r = M.trainEvaluate({ headers: H, rows, outcome, features: feats, model: type, params, folds: 3, seed: 4, importance: type === 'logit_enet' });
    assert.ok(r.summary.mean > 0.55, `${type}: CV ${r.summary.metric} ${r.summary.mean}`);
    const frozen = JSON.parse(JSON.stringify(r.finalModel)), applied = M.applyModel(frozen, H, rows);
    assert.equal(applied.n, r.n);
    assert.ok(applied.metrics && Number.isFinite(outcome.type === 'binary' ? applied.metrics.auc : applied.metrics.cIndex), type);
    if (type === 'logit_enet') assert.equal(r.importance[0].feature !== undefined, true);
  }
});

test('subtype discovery finds the planted clusters', () => {
  const genes = Array.from({ length: 12 }, (_, i) => ({ name: `gene_${String(i + 1).padStart(2, '0')}`, kind: 'numeric' }));
  const r = M.clusterAnalysis({ headers: H, rows, features: genes, kMin: 2, kMax: 5, seed: 1 });
  assert.equal(r.best.k, 3);
  const truth = rows.map(row => row[H.indexOf('subtype')]), map = new Map();
  r.best.labels.forEach((l, i) => { const k = `${l}|${truth[i]}`; map.set(k, (map.get(k) || 0) + 1); });
  const agree = [...new Set(r.best.labels)].reduce((s, l) => s + Math.max(...['A', 'B', 'C'].map(t => map.get(`${l}|${t}`) || 0)), 0) / rows.length;
  assert.ok(agree > 0.9, `cluster purity ${agree}`);
});

test('model card and TRIPOD+AI draft carry provenance and flag author-only items', () => {
  const r = M.trainEvaluate({ headers: H, rows, outcome: { type: 'binary', column: 'response', positive: '1' }, features: feats, model: 'logit_enet', folds: 3, seed: 2, subgroup: 'sex', importance: false });
  const card = modelCard(r, { dataName: demo.name, dataSha256: 'abc123', runId: 'run-1' });
  assert.equal(card.intendedUse.includes('Research use only'), true);
  assert.equal(card.data.sha256, 'abc123');
  assert.equal(card.model.seed, 2);
  const md = tripodDraft(r, { dataName: demo.name, dataSha256: 'abc123' });
  assert.match(md, /TRIPOD\+AI/); assert.match(md, /\[author to complete\]/); assert.match(md, /cross-validation/i); assert.match(md, /abc123/);
});
